import {castSceneV39} from './cast-v39.js';
// A few identifiable BD/assistant motifs support these original branches;
// similarly named people and private relationships are not merged.
const rows=[
 ['same-name','安妮有兩位，信只有一封','安妮余收到一封請她檢查模型的信，抬頭又寫公主。她把信拿給你看，問公司是不是準備用同名當跨部門整併方案。','先確認你找的是BD，還是另一位安妮。','收件人與實際工作','正確窗口名單','替兩位安妮發號碼牌，叫郵件先學會認人。','郵件沒有領號碼，寄件人倒是補上部門。安妮余把模型信轉回真正窗口，今天沒有因為同名多上一份班。'],
 ['owen-forward','歐文說幫一下，附件是整季','安妮余轉來歐文一段簡短的幫一下，附件卻有三個月合作排程。她也不知道哪一項已答應，只知道先被問能不能今天開始。','他只跟我說先跑起來。','合作期間與已承諾項目','主管確認信','替幫一下裝秤，超過一公斤就叫主管自己搬。','你們替附件秤出整季的重量，歐文終於回覆今天只要先列窗口。紙秤是假的，少接兩個月的口頭承諾是真的。',['bd']],
 ['martin-help','馬丁幫我，成了一種動詞','安妮余找你問資料，開頭先叫了馬丁，講到一半才發現你不是。她說叫習慣了，桌上那張工作單卻真的沒有列負責人。','不是叫你改名啦，是這件誰可以幫？','支援範圍與負責人','明確分工單','要求每次喊馬丁都支付一枚轉接幣。','安妮余笑著把馬丁從動詞改回人名。轉接幣沒有發行，工作單總算寫出誰回答、誰決定。',['bd']],
 ['proposal-guarantee','簡報有翻譯，承諾沒有','安妮余拿來合作簡報，中文寫可討論，英文卻像已經保證。她問要改哪一版，你發現兩邊都被歐文傳給不同窗口。','先別讓兩份語言各自簽一份約。','對外用語與承諾程度','同版對照稿','聘請問號當翻譯，禁止它一出國就變驚嘆號。','你們把保證改回待確認，問號留在兩份稿上。合作沒有因此少一項能力，只有少掉一個尚未答應的交期。',['bd']],
 ['boxing-calendar','拳賽還沒打，會議先打滿','安妮余對活動表說大家都想參加，BD會議卻一路排到晚上。你看對戰時間，第一回合已經被會議邀請占滿。','要不要先問他們哪一場真的散得了？','活動與會議的人員時間','確認過的行事曆','宣布會議連勝十二回合，直接頒發不退場金腰帶。','紙腰帶掛上會議室門把，安妮余才拿到可調整的時段。選手還沒出拳，至少不必同時存在兩個房間。'],
 ['crm-owner','客戶有名字，窗口是待認領','安妮余在CRM裡看到三位窗口，三個人都說只是協助。客戶來問下一步，她的訊息欄忽然變成大家共同的接待櫃台。','協助不是全部都交給我吧。','客戶主責與代理方式','可追蹤的負責欄','讓CRM舉辦認領大會，沒有主人的案子先穿救生衣。','案子沒有走上舞台，主管倒是選定一位主責。安妮余終於不用替三個協助同時回同一個問題。',['sales']],
 ['running-approval','歐文在跑，核准也在跑','歐文說晚點回覆，安妮余先收到他的跑步近況。她把待核准的合作內容排好，問你可不可以不要把運動配速當工作回覆時間。','我知道他在跑，不知道案子要不要跑。','核准期限與備用窗口','書面回覆日期','替核准信穿跑鞋，請它至少跑贏已讀。','跑鞋只是信件小圖，歐文卻回了真正的期限。安妮余把備用窗口補上，今天不用跟著配速等一份決定。',['bd']],
 ['nda-version','保密文件有四份公開版本','安妮余手上有四份檔名都叫最終版的保密文件，差異不是錯字，是合作對象。你問哪份送過，她打開三個寄件備份。','這次先別靠檔名猜。','文件版本與寄送對象','寄件版本清單','請最終版選出唯一繼承人，其他改姓草稿。','你們替文件排好世代，真正送出的那一份終於能被找到。繼承典禮沒辦，合作窗口少收到一封補充中的補充。',['bd']],
 ['calendar-white','空白行事曆，不等於沒在上班','安妮余的行事曆看起來很空，實際待辦卻寫滿別人的先幫一下。有人問她怎麼都沒安排，她把訊息欄轉給你看。','沒有會議框，不代表那些事不占時間。','臨時支援與可用工時','實際工作清單','替每句幫一下租一格行事曆，超住的付房租。','幫一下住滿了整週，大家才看見空白原來是被吃掉的時間。安妮余留下兩格真正能安排的新工作。'],
 ['trial-promised','免費試用，助理先付時間','合作方說只是先試試，安妮余拿到的清單卻含設定、教學和客製報表。她問免費範圍，收到一句先讓客戶感覺好。','感覺好能不能也有一個結束日期？','試用內容與停止條件','雙方確認的範圍','把免費試用關進沙漏，沙漏漏完就停止長功能。','沙漏沒有計費，清單倒是少了兩項客製。安妮余終於可以告訴對方今天能試什麼，而不是永久先試試。',['bd']],
 ['assistant-approval','助理名片，總監責任','專案表把核定合作條件放在安妮余名下。她指著自己的助理名片，問這算升遷，還是只升級了可以被追究的範圍。','核准的人是不是也該拿到核准權？','任務責任與決策權','授權層級表','替助理名片戴總監帽，看看預算會不會跟著長高。','紙帽高了十公分，權限一項也沒變。你們把核定欄改回真正有權的人，助理總算不用代理一個不存在的印章。',['project']],
 ['currency-quote','報價少一個字，差一整個匯率','安妮余發現對外報價只剩數字，幣別消失得比折扣快。客戶已回覆可以，你們卻不知道雙方答應的是哪一種可以。','先別把點頭當匯率鎖定。','幣別與含稅條件','完整書面報價','讓幣別坐報價正中央，數字只能當它的陪襯。','幣別沒有搶到封面，卻被補回每個價目。安妮余重寄後拿到確認，今天的業績不用靠匯率演猜謎。',['sales']],
 ['cc-chorus','副本合唱團，沒有主唱','安妮余被抄送進一封十五人的信，所有人都只回請參考。你聽她念到第七句，發現大家唱的是同一段，沒有任何人接主責。','抄送再多人，也不會自己長出答案。','主回覆人與補充順序','單一回覆窗口','替副本合唱團安排主唱甄選，禁止全員只唱和聲。','甄選最後選出真正要回覆的人。安妮余把自己的補充放進指定位置，合唱團少一點聲量，客戶多一份能看的答案。'],
 ['old-lead','老名單的新進度','安妮余被要求更新開發進度，表上卻是一批已經好幾個月沒回的窗口。她問算新案還是舊案，主管說先讓數字動起來。','有動過滑鼠不代表客戶有回覆。','名單狀態與開發定義','實際聯繫紀錄','替沉睡名單辦晨跑，跑不動的不要冒充新商機。','名單沒有起床，分類倒是終於分成已聯繫、待回覆與暫停。安妮余今天交的是進度，不是檔案重命名表演。',['bd']],
 ['logo-permission','合作Logo，先合作再說','安妮余帶著一張想放對方Logo的聯名稿來找你，合作方還沒確認能不能用。稿件卻已被排進明天的發布清單。','漂亮可以先看，權限不能先猜。','使用範圍與發布同意','對方確認信','替每顆Logo發入場證，沒有本人同意不准登台。','Logo留在候補圖層，正式稿先用中性圖示。安妮余等到許可才補上，沒有拿一次趕稿當成長期使用權。',['bd','design']],
 ['empty-seat','主管沒空，助理先開場','安妮余被請去代開合作會議，歐文還在別場。議程第一項卻要她拍板價錢，她看著門口，問這場是在等主管還是在等奇蹟。','我可以帶資料，不代表我能替他答應。','代理範圍與需核准事項','會議決議分欄','替空椅子裝上請稍候燈，沒有主管就不准自己點頭。','空椅子沒發言，你們把問題分成可回覆與待核准。安妮余把會議開完，沒有替缺席的人先花掉一筆未授權的承諾。',['bd']],
 ['leaving-question','別人的離場，不是你的去留表','幾位同事在談離開，安妮余也開始想自己下一步。她問你怎麼看，你發現群組已有人替她倒數，連本人都還沒決定。','我問的是想法，不是請大家替我簽。','本人決定與交接安排','自己確認的時間表','替每個擅自倒數的人發一個計時器，只能計自己的下班。','倒數回到每個人自己的手機裡。安妮余保留想走或留下的空間，今天沒因為聊天就被寫進離職名單。'],
 ['warm-comfort','舒適圈，怎麼只有一張轉寄椅','安妮余說想試新的工作，收到的建議卻都是先把現在那幾個人繼續服務好。她把自己的能力清單攤開，項目比職稱長很多。','下一步能不能也問我想學什麼？','發展目標與目前工作量','實際能力清單','把舒適圈畫成候車亭，沒有班表就不叫職涯規畫。','候車亭畫好後，你們列出真正想嘗試的任務。安妮余沒有立刻換工作，至少不再把等別人需要當成唯一方向。',['bd']],
 ['budget-owner','小額合作，大型追人','一筆小額合作申請在安妮余手上繞了三天，每個人都說金額不大不用問我。真的要付款時，所有人又要她補上誰同意。','不用問我的人，能不能先寫誰可以問？','費用歸屬與核准人','簽核紀錄','替每筆小額費用配一名監護人，禁止預算自己流浪。','費用終於有了核准窗口，沒有再隨金額變小而失去名字。安妮余交出完整申請，今天不靠訊息截圖拼成一個點頭。',['bd','finance']],
 ['invisible-change','會議只改一點，交付改整份','安妮余聽完會議說只有小調整，回來的清單卻多了一組流程。你問誰提的，她說大家各補一句，補到原來的版本認不出自己。','每人一點，合起來也要算一次範圍。','新增需求與原定交付','變更對照表','成立一點點累積稅，超過三點就強制重排工期。','累積稅沒有收錢，清單卻第一次把新增內容算出來。安妮余少說了一句只是小改，大家多看見一週的工作。',['project']],
 ['post-it-shift','便利貼的交接班','安妮余桌上貼著各組的小紙條，沒有日期也沒有狀態。有人取走一張，又問她為什麼沒做，你看得出她剛才根本不知道那是正式工作。','貼到桌上，不算我本人答應。','交辦方式與接單確認','可查的任務紀錄','給便利貼裝門鈴，沒被接聽的不得宣稱已交辦。','門鈴只是紙上的小圓點，大家倒是開始等本人確認。桌面仍有便利貼，至少少了幾張來路不明的責任。'],
 ['demo-tomorrow','明天Demo，今天才知道題目','安妮余收到合作展示邀請，對方期待的是另一種產品。歐文也坐下來看清單，才發現介紹信寫的範圍和現成系統不是同一回事。','我們先承認這兩份東西不一樣。','展示內容與對方預期','可演示項目表','替Demo辦身分驗證，禁止產品靠相似長相頂替。','歐文把能展示的項目重新寄出，安妮余不再替另一套想像準備歡迎詞。展示沒有變多，但終於跟現有東西長得一樣。',['bd'],['annie_yu','owen']],
 ['contact-chain','窗口的窗口，還有一位窗口','安妮余追合作資料，對方請她找另一個人，另一個人又說先問最初那位。你們連完箭頭，圖上是一個漂亮的圓。','我在找答案，不是在做圓形訓練。','決策人與資料持有人','窗口責任圖','把轉介圓環報名奧運，要求先跑完一圈的人回答問題。','圓環沒有拿金牌，合作方倒是指定一位整合窗口。安妮余終於能問下一題，不必先證明自己還在同一圈裡。',['bd']],
 ['lunch-handoff','午餐五分鐘，順便接一整案','安妮余路過你的便當，說客戶有個小問題可以先問嗎。螢幕打開後是整份新案，她自己也愣住，午餐差點改名專案啟動會。','那我們先吃，這個另外排時間吧。','詢問範圍與討論時間','正式會議邀請','請便當收專案啟動費，雞腿只當餐點不當顧問。','便當沒有開收據，安妮余把新案排進正常時段。今天的五分鐘真的只有五分鐘，你還能把那口飯吃熱。',['sales']],
 ['name-check','同名不是免費雙重任用','公主和安妮余一起收到同一張到場通知，兩人要準備的內容卻完全不同。她們站在你桌前，等你說明公司是不是只發明了一個安妮欄位。','請把部門也寫上去，這不是猜人名遊戲。','參與對象與各自準備','分工確認信','替安妮欄位加雙重驗證，輸入部門才准登入。','兩位安妮各拿到自己那份題目。欄位多了幾個字，今天少了一場因為同名開錯的會。',[],['annie_yu','princess']],
 ['holiday-pipeline','連假也要成長的管線','安妮余問連假期間要不要更新商機表，有人說數字不能停。她把已休假的窗口標出來，發現期待成長的人反而全部不在線上。','沒人回覆的那幾天，先別逼表格自己成交。','休假窗口與跟進節奏','真實回覆日期','替商機表申請補休，禁止假日欄位自動長業績。','表格沒去度假，你們卻把追蹤日移到對方回來之後。安妮余少發幾封沒人看的信，數字也不用假裝自己沒有日曆。',['bd']],
 ['one-file','一份資料，五種我要的不是這個','安妮余整理的合作摘要在五個群組被要求改成五種長度。每個人都說只要一份，她問你要不要先確認一份到底有幾個分身。','來源一份，閱讀方式可以分開。','共同資訊與各組用途','單一來源文件','替摘要辦分身許可證，未登記不得再長一個最終版。','你們留下同一份底稿，各組只看自己需要的段落。安妮余沒有再維護五個會互相打架的事實。',['bd']],
 ['status-stage','簡報上的助理，會議裡的主責','安妮余被安排報告所有合作案進度，卻拿不到有些案子的資訊。傑克也在場，問那些格子是不是該由真正主責補上，而不是看誰比較好叫。','我可以整理，不代表我知道別人沒講的部分。','彙整與實際交付責任','各案主責回覆','替未知欄位安排空椅子發表，請它誠實講不知道。','空椅子沒有硬報進度，傑克把缺漏退回各案窗口。安妮余報的是收到的資料，不是努力猜出來的同事近況。',['project'],['annie_yu','jack']],
 ['out-of-office','不在座位，先別自動派案','安妮余離座開會，桌上就多出兩份要她下班前回覆的文件。她回來問你發生什麼事，大家只記得有人說放她那邊就好。','人沒在，不代表桌子可以替她接受。','收件方式與回覆期限','本人確認紀錄','替桌子發拒接通知：本家具無權代表員工同意。','家具公告貼上去後，文件總算回到真正的交辦窗口。安妮余看完再決定接哪一項，桌子今天沒有代簽加班。'],
 ['direction-history','方向很多，路標只有昨天','歐文和安妮余一起看合作路線，兩人各記得一個不同版本。你翻開前次紀錄，原來昨天那個已經決定，今天只是尚未宣布被撤回。','改方向可以，先說哪一條不走了。','新舊方向與取消項目','決議變更紀錄','替每個新方向辦告別式，沒送走舊版不准再出發。','你們沒有真的奏哀樂，卻把取消項目寫清楚。安妮余終於不用同時替昨天和今天兩個歐文追同一個客戶。',['bd'],['annie_yu','owen']]
];
export const ANNIE_EVENTS_V39=rows.map((row,index)=>castSceneV39('annie_yu',index,row));
